/**
 * Shared decode types.
 * Canonical definitions for the web app and the browser extension.
 * The extension copies of src/lib are generated by scripts/sync-extension-lib.mjs,
 * so edit this file only.
 */

export interface SlangTerm {
  term: string;
  meaning: string;
  context: string;
}

/** A reply the creator can send, paired across the viewer's and creator's languages. */
export interface Suggestion {
  source: string;
  target: string;
}

export interface GeminiAnalysis {
  translatedText: string;
  sourceLanguage: string;
  slangTerms: SlangTerm[];
  toneTags: string[];
  suggestedReplies: Suggestion[];
  vibeScore: number;
}

export interface DecodeResult {
  originalText: string;
  translatedText: string;
  sourceLanguage: string;
  targetLanguage: string;
  toneTags: string[];
  vibeScore: number;
  suggestions: Suggestion[];
  status: string;
  safetyWarning?: string;
  slangTerms?: SlangTerm[];
  usedGemini?: boolean;
  /** Set when a Gemini key was supplied but the AI path could not be used. */
  aiError?: string;
  disambiguated?: boolean;
  disambiguationNote?: string;
  /** Summary of Personal Dictionary entries applied before decoding. */
  dictionaryNote?: string;
}

/** A user-defined slang entry: word -> meaning. */
export type CustomDictionary = Record<string, string>;
